// @lab {"title": "hologram STRESS: a command centre (globe, six arcs, ranked panel, live signal, scan, gauges, lock), an LLM explainer (token stream, three layers, 28-node attention mesh, next-word bars, callout), a calm three-tier teaching frame with a presenter", "styles": ["hologram"], "fx": {}, "dur": 43.0, "times": [12.4, 29.0, 42.5], "words": [{"w": "This", "s": 0.4, "e": 0.69}, {"w": "is", "s": 0.74, "e": 0.94}, {"w": "the", "s": 0.99, "e": 1.24}, {"w": "operations", "s": 1.29, "e": 1.83}, {"w": "console", "s": 1.88, "e": 2.29}, {"w": "for", "s": 2.34, "e": 2.59}, {"w": "our", "s": 2.64, "e": 2.88}, {"w": "global", "s": 2.93, "e": 3.31}, {"w": "network", "s": 3.36, "e": 3.77}, {"w": "Every", "s": 4.14, "e": 4.47}, {"w": "arc", "s": 4.52, "e": 4.77}, {"w": "is", "s": 4.82, "e": 5.02}, {"w": "live", "s": 5.07, "e": 5.36}, {"w": "traffic", "s": 5.41, "e": 5.82}, {"w": "between", "s": 5.87, "e": 6.29}, {"w": "six", "s": 6.34, "e": 6.58}, {"w": "regions", "s": 6.63, "e": 7.05}, {"w": "Frankfurt", "s": 7.42, "e": 7.91}, {"w": "is", "s": 7.96, "e": 8.17}, {"w": "running", "s": 8.22, "e": 8.63}, {"w": "hot", "s": 8.68, "e": 8.93}, {"w": "so", "s": 9.16, "e": 9.36}, {"w": "the", "s": 9.41, "e": 9.66}, {"w": "scan", "s": 9.71, "e": 10.0}, {"w": "flags", "s": 10.05, "e": 10.38}, {"w": "it", "s": 10.43, "e": 10.63}, {"w": "and", "s": 10.68, "e": 10.93}, {"w": "the", "s": 10.98, "e": 11.22}, {"w": "console", "s": 11.27, "e": 11.69}, {"w": "locks", "s": 11.74, "e": 12.07}, {"w": "on", "s": 12.12, "e": 12.32}, {"w": "before", "s": 12.37, "e": 12.74}, {"w": "customers", "s": 12.79, "e": 13.29}, {"w": "notice", "s": 13.34, "e": 13.71}, {"w": "Now", "s": 14.68, "e": 14.93}, {"w": "the", "s": 14.98, "e": 15.22}, {"w": "assistant", "s": 15.27, "e": 15.77}, {"w": "that", "s": 15.82, "e": 16.11}, {"w": "triages", "s": 16.16, "e": 16.57}, {"w": "those", "s": 16.62, "e": 16.95}, {"w": "alerts", "s": 17.0, "e": 17.38}, {"w": "Your", "s": 17.75, "e": 18.03}, {"w": "question", "s": 18.08, "e": 18.54}, {"w": "is", "s": 18.59, "e": 18.79}, {"w": "split", "s": 18.84, "e": 19.17}, {"w": "into", "s": 19.22, "e": 19.51}, {"w": "tokens", "s": 19.56, "e": 19.93}, {"w": "Each", "s": 20.3, "e": 20.59}, {"w": "layer", "s": 20.64, "e": 20.97}, {"w": "weighs", "s": 21.02, "e": 21.39}, {"w": "every", "s": 21.44, "e": 21.77}, {"w": "token", "s": 21.82, "e": 22.15}, {"w": "against", "s": 22.2, "e": 22.62}, {"w": "the", "s": 22.67, "e": 22.91}, {"w": "others", "s": 22.96, "e": 23.34}, {"w": "and", "s": 23.57, "e": 23.81}, {"w": "that", "s": 23.86, "e": 24.15}, {"w": "is", "s": 24.2, "e": 24.4}, {"w": "attention", "s": 24.45, "e": 24.95}, {"w": "Then", "s": 25.32, "e": 25.61}, {"w": "the", "s": 25.66, "e": 25.91}, {"w": "model", "s": 25.96, "e": 26.29}, {"w": "scores", "s": 26.34, "e": 26.71}, {"w": "the", "s": 26.76, "e": 27.0}, {"w": "next", "s": 27.05, "e": 27.34}, {"w": "word", "s": 27.39, "e": 27.68}, {"w": "and", "s": 27.73, "e": 27.98}, {"w": "picks", "s": 28.03, "e": 28.36}, {"w": "the", "s": 28.41, "e": 28.65}, {"w": "most", "s": 28.7, "e": 28.99}, {"w": "likely", "s": 29.04, "e": 29.41}, {"w": "one", "s": 29.46, "e": 29.71}, {"w": "So", "s": 30.68, "e": 30.88}, {"w": "think", "s": 30.93, "e": 31.26}, {"w": "of", "s": 31.31, "e": 31.52}, {"w": "it", "s": 31.57, "e": 31.77}, {"w": "in", "s": 31.82, "e": 32.02}, {"w": "three", "s": 32.07, "e": 32.4}, {"w": "tiers", "s": 32.45, "e": 32.78}, {"w": "Data", "s": 33.15, "e": 33.44}, {"w": "at", "s": 33.49, "e": 33.7}, {"w": "the", "s": 33.75, "e": 33.99}, {"w": "bottom", "s": 34.04, "e": 34.41}, {"w": "the", "s": 34.64, "e": 34.89}, {"w": "model", "s": 34.94, "e": 35.27}, {"w": "in", "s": 35.32, "e": 35.52}, {"w": "the", "s": 35.57, "e": 35.82}, {"w": "middle", "s": 35.87, "e": 36.24}, {"w": "and", "s": 36.47, "e": 36.72}, {"w": "people", "s": 36.77, "e": 37.14}, {"w": "at", "s": 37.19, "e": 37.39}, {"w": "the", "s": 37.44, "e": 37.69}, {"w": "top", "s": 37.74, "e": 37.99}, {"w": "The", "s": 38.36, "e": 38.6}, {"w": "analyst", "s": 38.65, "e": 39.07}, {"w": "stays", "s": 39.12, "e": 39.45}, {"w": "in", "s": 39.5, "e": 39.7}, {"w": "the", "s": 39.75, "e": 40.0}, {"w": "loop", "s": 40.05, "e": 40.33}, {"w": "and", "s": 40.38, "e": 40.63}, {"w": "approves", "s": 40.68, "e": 41.14}, {"w": "every", "s": 41.19, "e": 41.52}, {"w": "action", "s": 41.57, "e": 41.94}]}
/* STRESS TEST of the hologram engine (2026-10-16), not a lesson beat: one scene, three compositions on one HUD, each
 * pushed past the style's own density limits on purpose to see where the engine holds and where it breaks.
 *   1. a command centre (analysis): a spinning globe with six labelled regions and six arcs of traffic, a ranked
 *      panel, a live signal with an anomaly, a radial scan, three gauges, a lock on the hot region;
 *   2. an LLM explainer: a token stream, three model layers as framed bands, a 28-node mesh of attention links with
 *      packets climbing it, next-word probability bars (H.bars), a confidence gauge, a callout on attention;
 *   3. a calmer teaching frame: three tiers as a flow pointing up (data to people), a highlighted tier with a callout,
 *      an approval card, a roles panel and a presenter (the generic "ava" rig: the style has no character kit, and
 *      the engine says so with holo_character_kit).
 * After the engine fixes (2026-10-16): bars, the WARN word on a panel set, the emphasised attention link, the upward
 * flow, labels over globe arcs with land, gauge units apart, a labelled blip. Six labelled globe points are past the
 * guide's three on purpose (holo_globe_dense warns).
 * Every number is illustrative (a hypothetical console); in a lesson each would come from the knowledge sheet. */
Loom.scene("hologram_stress", {
  build(ctx) {
    const W = ctx.engine, H = W.hud(ctx, { name: "hud" });
    const cue = (s) => ctx.cue(s);
    // a region at its city's real place (Natural Earth, runtime/geo.js); naming Loom.geo also puts the land on the globe
    const city = (id, nm, label) => { const [lon, lat] = Loom.geo.city(nm); return { id, lon, lat, label }; };

    // the far layer: one still hex field for the whole scene
    H.grid("field_hex", { x: 0, y: 0, w: 1920, h: 1080, kind: "hex", cell: 34, opacity: 0.08, at: 0.1 });
    // the analysis compositions sit on the dark stage (a lift behind the live view, a strong vignette); the calm
    // briefing frame at the end does not
    const STG = H.stage("stage", { focus: [960, 500], at: 0.1 });

    // ======================================================================== 1. COMMAND CENTRE
    const T1 = H.title("c_head", { x: 96, y: 76, w: 1100, h: 110, kicker: "Global operations, live", text: "Traffic between our six regions", role: "lead", at: 0.3 });

    const G = H.globe("c_globe", { cx: 960, cy: 500, r: 280, at: cue("operations") - 0.3, lat: 7, lon: 16, tilt: 20, lon0: -75,
      spin: 12, spinFrom: cue("global network"), spinTo: cue("Frankfurt") + 0.4,
      points: [
        { id: "fra", lon: 8.7, lat: 50.1, label: "Frankfurt", status: "warn" },
        { id: "vir", lon: -77.5, lat: 38.9, label: "Virginia" },
        city("sao", "S\u00e3o Paulo", "Sao Paulo"),
        city("mum", "Mumbai", "Mumbai"),
        city("sin", "Singapore", "Singapore"),
        city("syd", "Sydney", "Sydney"),
      ],
      arcs: [
        { from: "fra", to: "vir", at: cue("Every arc"), dur: 0.9, status: "warn", every: 1.5, until: 13.6 },
        { from: "fra", to: "mum", at: cue("arc") + 0.3, dur: 0.9, status: "warn", every: 1.7, until: 13.6 },
        { from: "fra", to: "sin", at: cue("live") , dur: 1.0, status: "warn", every: 1.9, until: 13.6 },
        { from: "vir", to: "sao", at: cue("traffic"), dur: 0.8, status: "accent", every: 1.6, until: 13.6 },
        { from: "mum", to: "sin", at: cue("between"), dur: 0.8, status: "accent", every: 1.4, until: 13.6 },
        { from: "sin", to: "syd", at: cue("six"), dur: 0.8, status: "accent", every: 1.8, until: 13.6 },
      ] });

    const RANK = H.panel("c_rank", { x: 96, y: 214, w: 520, h: 440, depth: "near", title: "Busiest regions", at: cue("global") - 0.3, by: cue("network") + 1.4, rows: [
      ["Frankfurt", "38.2k/s"], ["Virginia", "31.0k/s"], ["Singapore", "24.6k/s"],
      ["Sao Paulo", "12.9k/s"], ["Mumbai", "9.8k/s"], ["Sydney", "7.1k/s"],
    ] });
    RANK.set(0, "41.7k/s", cue("running hot"), "warn");

    const WV = H.wave("c_wave", { x: 96, y: 690, w: 520, h: 200, label: "Requests a second, Frankfurt", freq: 2.4, amp: 0.24, seed: "fra",
      at: cue("live") - 0.3, t0: cue("traffic"), t1: 13.6, anomaly: { at: cue("running hot"), dur: 5.0, status: "alert", x: 0.74 } });

    const SC = H.scanner("c_scan", { cx: 1572, cy: 344, r: 130, label: "Edge scan", at: cue("Every") - 0.3, speed: 110,
      sweeps: [[cue("scan"), 12.9]], blips: [
        { angle: 40, dist: 0.7, status: "info" }, { angle: 120, dist: 0.45, status: "info" },
        { angle: 210, dist: 0.8, status: "info" }, { angle: 300, dist: 0.55, status: "warn", label: "FRA edge" },
      ] });

    const g1 = H.gauge("c_rate", { cx: 1386, cy: 680, r: 70, value: 1.8, max: 2.5, unit: "k/s", decimals: 1, label: "Rate", at: cue("six") - 0.3 });
    const g2 = H.gauge("c_err", { cx: 1566, cy: 680, r: 70, value: 2.6, max: 10, unit: "%", decimals: 1, warn: 1, alert: 5, label: "Errors", at: cue("six") - 0.15 });
    const g3 = H.gauge("c_p95", { cx: 1746, cy: 680, r: 70, value: 0.41, max: 1, unit: "s", decimals: 2, warn: 0.3, alert: 0.6, label: "p95", at: cue("six") });
    g2.set(5.8, cue("flags"), 1.0);

    const L1 = H.lock(G.pointAt("fra", cue("console locks")), { at: cue("console locks"), label: "Frankfurt, 92% load", labelPos: "above", labelAlign: "left", status: "alert" });

    // power the command centre down before the next composition
    const off1 = 13.85;
    L1.release(off1 - 0.2);
    H.power(T1, "down", off1);
    H.power(RANK, "down", off1 + 0.05);
    H.power(G, "down", off1 + 0.1);
    H.power(WV, "down", off1 + 0.15);
    H.power(SC, "down", off1 + 0.15);
    H.power(g1, "down", off1 + 0.2); H.power(g2, "down", off1 + 0.25); H.power(g3, "down", off1 + 0.3);

    // ======================================================================== 2. LLM EXPLAINER
    const T2 = H.title("m_head", { x: 96, y: 76, w: 1200, h: 110, kicker: "Inside the triage assistant", text: "How a language model picks the next word", role: "lead", at: cue("Now") - 0.2 });

    const TOK = ["Why", "is", "Frank", "furt", "running", "hot", "?"];
    const STREAM = H.readout("m_stream", { x: 96, y: 214, w: 340, h: 700, title: "Token stream", tags: false, timeW: 64, at: cue("question") - 0.3, rows: [] });
    TOK.forEach((tk, i) => STREAM.push([String(i + 1).padStart(2, "0"), tk], cue("split") + i * 0.28));

    const CONF = H.gauge("m_conf", { cx: 1627, cy: 560, r: 92, value: 0, max: 100, unit: "%", label: "Confidence", at: cue("question") });
    CONF.set(62, cue("picks"), 1.0);

    // three model layers as framed bands, each named by a tag; the mesh of units and attention links sits over them
    const MX = 480, MY = 210, colX = (i) => 200 + i * 113, rowY = [380, 270, 160, 50];   // tokens, L1, L2, L3
    const bands = [];
    [["LAYER 1", 1], ["LAYER 2", 2], ["LAYER 3", 3]].forEach(([word, r], k) => {
      const y = MY + rowY[r] - 48;
      const F = H.frame("m_layer" + r, { x: 470, y, w: 920, h: 96, at: cue("assistant") - 0.3 + k * 0.2, overlaps: ["m_mesh"] });
      H.tag(F.E, F.g, 12, 27, "info", cue("assistant") + 0.1 + k * 0.2, { word });
      bands.push(F);
    });
    const nodes = [], links = [];
    TOK.forEach((tk, i) => {
      nodes.push({ id: "t" + i, x: colX(i), y: rowY[0], label: tk, r: 16 });
      for (let r = 1; r <= 3; r++) nodes.push({ id: "l" + r + "_" + i, x: colX(i), y: rowY[r], r: 13 });
    });
    for (let r = 1; r <= 3; r++) {
      const below = (i) => (r === 1 ? "t" + i : "l" + (r - 1) + "_" + i);
      for (let i = 0; i < TOK.length; i++) for (const j of [i - 1, i, i + 1]) if (j >= 0 && j < TOK.length) links.push([below(j), "l" + r + "_" + i]);
    }
    links.push(["l1_2", "l2_5"], ["l1_3", "l2_5"], ["l1_0", "l2_4"]);           // long-range attention
    const M = H.mesh("m_mesh", { x: MX, y: MY, w: 900, h: 460, nodes, links, at: cue("assistant"), by: cue("alerts") + 0.6, overlaps: ["m_layer1", "m_layer2", "m_layer3"] });
    // packets climb the columns once the tokens are in; the attention path carries one on the word
    let tp = cue("weighs");
    for (let k = 0; k < 24; k++, tp += 0.36) { const i = (k * 3) % TOK.length; M.send(["t" + i, "l1_" + i, "l2_" + i, "l3_" + i], tp, { dur: 1.3 }); }
    // the attention links stand out among fifty: weight and glow, and the rest dim on the word
    M.linkStatus("l1_2", "l2_5", "accent", cue("attention"), { dim: 0.3 });
    M.linkStatus("l1_3", "l2_5", "accent", cue("attention"), { dim: 0.3 });
    M.send(["l1_2", "l2_5", "l3_5"], cue("attention") + 0.2, { dur: 1.4 });
    const hot = M.node("l2_5").rect;
    H.callout("m_note", { to: [hot.x + hot.w / 2, hot.y + hot.h / 2], from: [1420, 262], side: "right", w: 340,
      text: "Attention: hot looks back at Frank and furt", at: cue("attention"), until: 30.0 });

    // the next word: filled bars with their odds outside them (the lower centre, under the model)
    const NW = H.bars("m_next", { x: 470, y: 668, w: 920, h: 258, pad: 20, rowH: 40, title: "Next word", max: 100, unit: "%",
      at: cue("scores") - 0.3, by: cue("word") + 0.4, rows: [["load", 62], ["traffic", 21], ["heat", 9], ["demand", 5]] });
    NW.mark(0, "ok", cue("picks"), { word: "PICKED" });

    // a slow push onto the attention, then back to the whole before the pick
    H.push({ to: [930, 420], scale: 1.18, t0: cue("attention") - 0.3, t1: cue("attention") + 1.3 });
    H.pull({ t0: cue("model scores") - 0.2, t1: cue("model scores") + 1.3 });

    const off2 = 30.15;
    [T2, STREAM, CONF, M, NW].concat(bands).forEach((h, k) => H.power(h, "down", off2 + (k % 6) * 0.05));
    H.power(STG, "down", off2 + 0.3);

    // ======================================================================== 3. TEACHING FRAME (calm)
    H.title("t_head", { x: 120, y: 92, w: 1200, h: 150, kicker: "Where people fit", text: "Three tiers, one person in the loop", at: cue("So think") - 0.2 });
    // the data flows up: the first step sits at the bottom and the arrows point up
    const F = H.flow("t_tiers", { x: 120, y: 290, w: 680, h: 610, dir: "up", index: false, at: cue("three tiers") - 0.3, by: cue("top"), steps: [
      { label: "Data", sub: "logs, metrics and traffic" },
      { label: "Model", sub: "triages alerts, drafts actions" },
      { label: "People", sub: "the analyst decides and approves" },
    ] });
    F.packet(cue("bottom"), { from: 0, to: 2, dur: 3.4 });
    F.step(2, "ok", cue("approves"));                 // the brackets turn green and the OK word shows
    H.callout("t_note", { to: [800, 368], from: [880, 300], side: "right", w: 380, status: "ok",
      text: "Every containment action waits for a person", at: cue("approves") - 0.2 });
    H.card("t_card", { x: 920, y: 380, w: 480, h: 240, kicker: "Human approval", value: 100, unit: "%", label: "of containment actions", status: "ok", at: cue("analyst") - 0.3 });
    H.panel("t_roles", { x: 920, y: 646, w: 480, h: 276, title: "Who does what", at: cue("stays") - 0.3, by: cue("loop") + 0.6, rows: [
      ["Data", "collects"], ["Model", "drafts"], ["Analyst", "decides", "ok"],
    ] });
    const ana = ctx.character("t_analyst", "ava", { x: 1620, y: 905, scale: 0.6, flip: true, parent: H.layer("mid") });
    if (ana) {
      ctx.m.settle(ana.E, cue("people") - 0.3);
      ana.pose("present", cue("people"), { dur: 0.5 });
      ana.look(-1, 0, cue("people"));
    }
  },
});
